package com.bank.styles.service;

import org.springframework.stereotype.Service;
import java.math.BigDecimal;

// One shared business service. All three API styles are thin adapters over it,
// proving the style is a transport choice, not a business-logic choice.
@Service
public class AccountService {
    public BigDecimal balanceOf(String accountNumber) {
        return "SAV2001".equals(accountNumber)
                ? new BigDecimal("1000000") : BigDecimal.ZERO;
    }
}
