package com.bank.styles.rest;

import com.bank.styles.service.AccountService;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.Map;

// REST: human-readable JSON, resource URL, cacheable, browser-friendly.
@RestController
@RequestMapping(value = "/api/v1/accounts", produces = MediaType.APPLICATION_JSON_VALUE)
public class AccountRestController {

    private final AccountService service;
    public AccountRestController(AccountService service) { this.service = service; }

    @GetMapping("/{number}/balance")
    public Map<String, BigDecimal> balance(@PathVariable String number) {
        return Map.of("balance", service.balanceOf(number));
    }
}
