package com.bank.styles.grpc;

import com.bank.styles.gen.*;
import com.bank.styles.service.AccountService;
import io.grpc.stub.StreamObserver;
import net.devh.boot.grpc.server.service.GrpcService;

// gRPC: binary protobuf over HTTP/2, typed generated stub, fast internal calls.
@GrpcService
public class AccountGrpcService extends AccountServiceGrpc.AccountServiceImplBase {

    private final AccountService service;
    public AccountGrpcService(AccountService service) { this.service = service; }

    @Override
    public void getBalance(AccountRef ref, StreamObserver<Balance> obs) {
        long paise = service.balanceOf(ref.getNumber()).movePointRight(2).longValueExact();
        obs.onNext(Balance.newBuilder().setBalancePaise(paise).build());
        obs.onCompleted();
    }
}
