package com.bank.styles.graphql;

import com.bank.styles.service.AccountService;
import org.springframework.graphql.data.method.annotation.*;
import org.springframework.stereotype.Controller;
import java.math.BigDecimal;

// GraphQL: single endpoint, client picks the exact fields it wants.
@Controller
public class AccountGraphqlResolver {

    private final AccountService service;
    public AccountGraphqlResolver(AccountService service) { this.service = service; }

    @QueryMapping
    public AccountView account(@Argument String number) {
        return new AccountView(number, service.balanceOf(number));
    }

    // Simple view type the schema maps onto.
    public record AccountView(String number, BigDecimal balance) { }
}
